reproductionPrograms.frontendProbe:
import {mkdirSync,mkdtempSync,readFileSync,rmSync,writeFileSync} from "node:fs";
import {tmpdir} from "node:os"; import {join,resolve} from "node:path";
const root=mkdtempSync(join(tmpdir(),"jadpo-rm306-review-"));
const bin=resolve("jadpo/target/debug/jadpo"),base=readFileSync("tests/compile/pass/173_scheduled_job.jadpo","utf8");
const app=join(root,"app.jadpo");
const cases={
positive:base,
rounded_fractional_large:base.replace("15m","9007199254740991.4ms"),
rounded_sub_millisecond:base.replace("15m","0.000999999999999999999999999999999999s"),
rounded_fractional_unit:base.replace("15m","1.00000000000000001ms"),
nullable_parameter:base.replace("at: JobRunAt","at: JobRunAt?"),
unknown_constructor_owner:base.replace("JobRunAt(clock.now)","Wrong.JobRunAt(clock.now)"),
raw_clock:base.replace("JobRunAt(clock.now)","clock.now"),
primitive_signature:base.replace("at: JobRunAt","at: Instant"),
generic_wrapper:base.replace("at: JobRunAt","at: JobRunAt<Instant>"),
extra_principal:base.replace("JobRunAt(clock.now)","JobRunAt(clock.now), principal"),
nested_call:base.replace("JobRunAt(clock.now)","JobRunAt(scan(JobRunAt(clock.now)))"),
invalid_then_valid_clause:base.replace("concurrency: singleton","concurrency: parallel concurrency: singleton"),
unknown_nested_clause:base.replace("retry: next_schedule","payload: { run: scan(JobRunAt(clock.now)) } retry: next_schedule"),
call_job:base+'\naction invoke(at: JobRunAt) -> Unit { var result = overdue_reminders(at) }',
export_job:base.replace("job overdue_reminders","public job overdue_reminders"),
qualified_receiver:base.replace("run: scan","run: Forged.scan"),
subtype_chain:base.replace("type JobRunAt = Instant {}","type ParentTime = Instant {}\ntype JobRunAt = ParentTime {}"),
nullable_parent:base.replace("JobRunAt = Instant","JobRunAt = Instant?"),
constrained_type:base.replace("JobRunAt = Instant {}","JobRunAt = Instant { max_length: 8 }"),
missing_clause:base.replace("concurrency: singleton","")
};
try {
for(const [name,source] of Object.entries(cases)){
writeFileSync(app,source);
const result=Bun.spawnSync([bin,"check",app,"--diagnostic-format=json"],{stdout:"pipe",stderr:"pipe"});
const json=JSON.parse(result.stdout.toString());
console.log(JSON.stringify({case:name,exitCode:result.exitCode,status:json.status,rules:json.diagnostics.map((d:any)=>d.ruleId)}));
}
writeFileSync(app,base);
const built=Bun.spawnSync([bin,"build",app],{stdout:"pipe",stderr:"pipe"});
console.log(JSON.stringify({case:"target_build",exitCode:built.exitCode,stdout:built.stdout.toString(),stderr:built.stderr.toString()}));
}finally{rmSync(root,{recursive:true,force:true});}

reproductionPrograms.auditAndVisibilityProbe:
import {mkdirSync,mkdtempSync,readFileSync,rmSync,writeFileSync,existsSync} from "node:fs";
import {tmpdir} from "node:os"; import {join,resolve} from "node:path";
const root=mkdtempSync(join(tmpdir(),"jadpo-rm306-audit-")),bin=resolve("jadpo/target/debug/jadpo");
const base=readFileSync("tests/compile/pass/173_scheduled_job.jadpo","utf8");
try{
for(const duration of ["15m","9007199254740991.4ms","0.000999999999999999999999999999999999s","1.00000000000000001ms"]){
const dir=join(root,"case"+duration.length+"-"+duration.slice(0,3).replaceAll(".","_"));mkdirSync(dir,{recursive:true});
const app=join(dir,"app.jadpo");writeFileSync(app,base.replace("15m",duration));
const result=Bun.spawnSync([bin,"artifacts",app],{stdout:"pipe",stderr:"pipe"});
if(result.exitCode!==0)throw new Error(result.stderr.toString());
const audit=JSON.parse(readFileSync(join(dir,"build/audit/jobs.json"),"utf8"));
console.log(JSON.stringify({case:"interval_audit",sourceDuration:duration,job:audit.jobs[0]}));
const built=Bun.spawnSync([bin,"build",app],{stdout:"pipe",stderr:"pipe"});
console.log(JSON.stringify({case:"fail_closed",sourceDuration:duration,exitCode:built.exitCode,targetAppExists:existsSync(join(dir,"build/target/app.ts"))}));
}
const definitions="module shared.jobs\npublic type JobRunAt = Instant {}\npublic action scan(at: JobRunAt) -> Unit {}\n";
const job=base.slice(base.indexOf("job overdue_reminders"));
for(const [name,defs,imports] of [
["public_import",definitions,"import shared.jobs { scan, JobRunAt }"],
["no_import",definitions,""],
["private_action",definitions.replace("public action","action"),"import shared.jobs { scan, JobRunAt }"],
["private_constructor",definitions.replace("public type","type"),"import shared.jobs { scan, JobRunAt }"],
["missing_constructor_import",definitions,"import shared.jobs { scan }"]
]){
const dir=join(root,name);mkdirSync(dir);
writeFileSync(join(dir,"shared.jadpo"),defs);writeFileSync(join(dir,"consumer.jadpo"),"module app.jobs\n"+imports+"\n"+job);
const result=Bun.spawnSync([bin,"check",dir,"--diagnostic-format=json"],{stdout:"pipe",stderr:"pipe"});
const json=JSON.parse(result.stdout.toString());console.log(JSON.stringify({case:name,status:json.status,rules:json.diagnostics.map((d:any)=>d.ruleId)}));
}
const dir=join(root,"no_jobs");mkdirSync(dir);writeFileSync(join(dir,"app.jadpo"),base.slice(0,base.indexOf("job overdue_reminders")));
const result=Bun.spawnSync([bin,"artifacts",dir],{stdout:"pipe",stderr:"pipe"});
console.log(JSON.stringify({case:"no_jobs_artifact",exitCode:result.exitCode,jobsArtifactExists:existsSync(join(dir,"build/audit/jobs.json"))}));
}finally{rmSync(root,{recursive:true,force:true});}

reproductionPrograms.lspProbe:
import {mkdtempSync,readFileSync,writeFileSync,rmSync} from "node:fs"; import {tmpdir} from "node:os"; import {join,resolve} from "node:path"; import {pathToFileURL} from "node:url";
const root=mkdtempSync(join(tmpdir(),"jadpo-rm306-lsp-"));const text=readFileSync("tests/compile/pass/173_scheduled_job.jadpo","utf8"),file=join(root,"app.jadpo");writeFileSync(file,text);
const uri=pathToFileURL(file).href,position=(offset:number)=>{const lines=text.slice(0,offset).split("\n");return {line:lines.length-1,character:lines.at(-1)!.length};};
const messages=[
{jsonrpc:"2.0",id:1,method:"initialize",params:{rootUri:pathToFileURL(root).href,capabilities:{}}},
{jsonrpc:"2.0",method:"initialized",params:{}},
{jsonrpc:"2.0",method:"textDocument/didOpen",params:{textDocument:{uri,languageId:"jadpo",version:1,text}}},
{jsonrpc:"2.0",id:2,method:"textDocument/definition",params:{textDocument:{uri},position:position(text.indexOf("run: scan")+5)}},
{jsonrpc:"2.0",id:3,method:"textDocument/definition",params:{textDocument:{uri},position:position(text.indexOf("JobRunAt(clock"))}},
{jsonrpc:"2.0",id:4,method:"textDocument/references",params:{textDocument:{uri},position:position(text.indexOf("JobRunAt(clock")),context:{includeDeclaration:true}}},
{jsonrpc:"2.0",id:5,method:"textDocument/documentSymbol",params:{textDocument:{uri}}},
{jsonrpc:"2.0",id:6,method:"shutdown",params:null},
{jsonrpc:"2.0",method:"exit",params:null}
];
try{
const input=Buffer.concat(messages.map(m=>{const bytes=Buffer.from(JSON.stringify(m));return Buffer.concat([Buffer.from("Content-Length: "+bytes.length+"\r\n\r\n"),bytes]);}));
const result=Bun.spawnSync([resolve("jadpo/target/debug/jadpo"),"lsp"],{stdin:input,stdout:"pipe",stderr:"pipe"});
const output=result.stdout;let cursor=0;const replies:any[]=[];
while(cursor<output.length){const end=output.indexOf("\r\n\r\n",cursor);if(end<0)break;const length=Number(/Content-Length: (\d+)/i.exec(output.subarray(cursor,end).toString())?.[1]);cursor=end+4;replies.push(JSON.parse(output.subarray(cursor,cursor+length).toString()));cursor+=length;}
for(const reply of replies.filter(x=>[2,3,4,5].includes(x.id)))console.log(JSON.stringify(reply));
if(result.exitCode!==0)throw new Error(result.stderr.toString());
const r2=replies.find(x=>x.id===2)?.result,r3=replies.find(x=>x.id===3)?.result,r4=replies.find(x=>x.id===4)?.result;
if((Array.isArray(r2)?r2[0]:r2)?.range.start.line!==1||(Array.isArray(r3)?r3[0]:r3)?.range.start.line!==0||r4?.length!==3)throw new Error("job LSP callee/type references do not match");
console.log(JSON.stringify({case:"lsp",status:"passed",calleeDefinitionLine:1,constructorDefinitionLine:0,constructorReferences:3}));
}finally{rmSync(root,{recursive:true,force:true});}
